"""Determine set of effective triggers.

    :param triggers: list of configured triggers.
    :type triggers: List[str]
    :param add_triggers: additional triggers.
    :type add_triggers: List[str]
    :param use_triggers: triggers shall be applied.
    :type use_triggers: bool
    :return: list of effective triggers.
    :rtype: List[str]
    """
def determine_triggers(triggers: Any, add_triggers: Any, use_triggers: Any) -> object {
    if use_triggers {
        triggers_ = triggers;
        triggers_.extend(add_triggers);
    } else {
        triggers_ = [];
    }
    return triggers_;
}

test_blocks:
test "t0" {
    assert (determine_triggers(["a", "b", "c"], ["b", "c", "d"], False) == []);;
}

test "t1" {
    assert (determine_triggers(['a'], [], True) == ['a']);;
}

test "t2" {
    assert (determine_triggers([], ["b", "c", "d"], True) == ["b", "c", "d"]);;
}

test "t3" {
    assert (determine_triggers(['a'], ['b', 'c'], True) == ['a', 'b', 'c']);;
}

test "t4" {
    assert (determine_triggers(['foo'], ['bar'], False) == []);;
}

test "t5" {
    assert (
        determine_triggers(['a', 'b', 'c'], ['d', 'e', 'f'], True)
        == ['a', 'b', 'c', 'd', 'e', 'f']
    );;
}

test "t6" {
    assert (determine_triggers(['foo'], [], False) == []);;
}

test "t7" {
    assert (determine_triggers(['foo'], [], True) == ['foo']);;
}

test "t8" {
    assert (determine_triggers(['my_trigger'], ['my_add_trigger'], False) == []);;
}

test "t9" {
    assert (determine_triggers(['a'], ['b'], True) == ['a', 'b']);;
}

test "t10" {
    assert (
        determine_triggers(['my_trigger'], ['my_add_trigger'], True)
        == ['my_trigger', 'my_add_trigger']
    );;
}

test "t11" {
    assert (determine_triggers(['a'], ['b'], False) == []);;
}

test "t12" {
    assert (determine_triggers([], ["b", "c", "d"], None) == []);;
}

test "t13" {
    assert (determine_triggers([], ["b", "c", "d"], False) == []);;
}

test "t14" {
    assert (determine_triggers(None, ["b", "c", "d"], False) == []);;
}

test "t15" {
    assert (
        determine_triggers(['a', 'b', 'c'], ['d', 'e'], True)
        == ['a', 'b', 'c', 'd', 'e']
    );;
}

test "t16" {
    assert (determine_triggers(["a", "b", "c"], ["b", "c", "d"], None) == []);;
}

test "t17" {
    assert (determine_triggers(['a'], ['b', 'c'], False) == []);;
}

test "t18" {
    assert (determine_triggers(['a', 'b'], ['c'], False) == []);;
}

test "t19" {
    assert (determine_triggers(['a', 'b', 'c'], ['d'], True) == ['a', 'b', 'c', 'd']);;
}

test "t20" {
    assert (determine_triggers(None, ["b", "c", "d"], None) == []);;
}

test "t21" {
    assert (determine_triggers(['a'], [], False) == []);;
}

test "t22" {
    assert (determine_triggers(['a', 'b'], ['c'], True) == ['a', 'b', 'c']);;
}
